namespace HybridCPU_ISE.Tests.Architecture;
public sealed class Rf129axReplayEpochAuthorityDecisionTests
{[Fact] public void PaperAssignsReplayEpochAllocationAndZeroAuthorityToLoopBuffer(){string p=File.ReadAllText(Path.Combine(Root(),"ResearchPaper","section","md base","7_Replay_Stable_Placement_Replay_Tokens_and_Execution_Boundaries.md"));Assert.Contains("`ReplayEpoch` is the loop-buffer-owned identity",p,StringComparison.Ordinal);Assert.Contains("positive, non-wrapping `UInt64`",p,StringComparison.Ordinal);Assert.Contains("zero is never",p,StringComparison.Ordinal);Assert.Contains("context may retain the most recently allocated nonzero value",p,StringComparison.Ordinal);Assert.Contains("compatibility transport only",p,StringComparison.Ordinal);Assert.Contains("evidence only",p,StringComparison.Ordinal);Assert.Contains("`AssistEpochId` remains a",p,StringComparison.Ordinal);}private static string Root(){DirectoryInfo? c=new(AppContext.BaseDirectory);while(c is not null){if(Directory.Exists(Path.Combine(c.FullName,"ResearchPaper")))return c.FullName;c=c.Parent;}throw new DirectoryNotFoundException();}}
